/* From Uiverse.io by benjimich - Tags: input */
.__UIV_SCOPE__ .container {
  display: flex;
  justify-content: center;
  align-items: center;
  height: 35px;
}

.__UIV_SCOPE__ .input {
  max-width: 190px;
  height: 100%;
  outline: none;
  font-size: 14px;
  font-weight: 500;
  background-color: #53535f;
  caret-color: #f7f7f8;
  color: #fff;
  padding: 7px 10px;
  border: 2px solid transparent;
  border-top-left-radius: 7px;
  border-bottom-left-radius: 7px;
  margin-right: 1px;
  transition: all .2s ease;
}

.__UIV_SCOPE__ .input:hover {
  border: 2px solid rgba(255, 255, 255, 0.16);
}

.__UIV_SCOPE__ .input:focus {
  border: 2px solid #a970ff;
  background-color: #0e0e10;
}

.__UIV_SCOPE__ .search__btn {
  border: none;
  cursor: pointer;
  background-color: rgba(42, 42, 45, 1);
  border-top-right-radius: 7px;
  border-bottom-right-radius: 7px;
  height: 100%;
  width: 30px;
  display: flex;
  justify-content: center;
  align-items: center;
}

.__UIV_SCOPE__ .search__btn:hover {
  background-color: rgba(54, 54, 56, 1);
}
